text = display_path.read_text(encoding="utf-8")

old = """        for (int column = 0;
             column < font.Width;
             column++)
        {
            for (int row = 0;
                 row < font.Height;
                 row++)
            {
                if (glyph[column] &
                    (1 << row))
                {
                    FillRectangle(
                        x + column * scale,
                        y + row * scale,
                        scale,
                        scale,
                        color);
                }
            }
        }
"""

new = """        for (int row = 0;
             row < font.Height;
             row++)
        {
            uint8_t rowBits =
                glyph[row];

            for (int column = 0;
                 column < font.Width;
                 column++)
            {
                uint8_t mask =
                    static_cast<uint8_t>(
                        0x80 >> column);

                if ((rowBits & mask) != 0)
                {
                    FillRectangle(
                        x + column * scale,
                        y + row * scale,
                        scale,
                        scale,
                        color);
                }
            }
        }
"""

if old not in text:
    raise SystemExit(
        "STOP: Display.cpp does not match the expected swappable-font baseline.")

text = text.replace(old, new, 1)
display_path.write_text(text, encoding="utf-8")

print("8x12 BadgeSans font upgrade applied.")
